const fs = require('fs');
const lockPath = 'D:\\n8n-card-pipeline\\pipeline.lock';

if (fs.existsSync(lockPath)) {
  const stats = fs.statSync(lockPath);
  const ageMs = Date.now() - stats.mtimeMs;
  const maxAgeMs = 10 * 60 * 1000; // 10 минут

  if (ageMs < maxAgeMs) {
    return [];
  }
  // замок старше 10 минут — считаем зависшим, снимаем сами
  fs.unlinkSync(lockPath);
}

const staticData = $getWorkflowStaticData('global');
const lastId = staticData.lastUpdateId || 0;

const updates = $input.first().json.result || [];
const newMessages = updates.filter(u => u.update_id > lastId);

if (newMessages.length > 0) {
  staticData.lastUpdateId = newMessages[newMessages.length - 1].update_id;
}
// Замок здесь больше НЕ создаётся — только проверяется. Создание перенесено
// в "Разделение темы и пожелания", то есть срабатывает только для реальных
// запросов на генерацию, а не для лёгких команд вроде /start.

return newMessages.map(u => ({ json: u }));

const fs = require('fs');
const lockPath = 'D:\\n8n-card-pipeline\\pipeline.lock';

if (fs.existsSync(lockPath)) {
  fs.unlinkSync(lockPath);
}

return $input.all();

const response = $json.result || $json;
const base64Image = response.image;

if (!base64Image) {
  // Генерация могла быть отклонена фильтром безопасности Cloudflare (NSFW и т.п.)
  // или упасть по другой причине — не роняем узел, а помечаем этот конкретный
  // вариант как ошибочный, чтобы пайплайн мог продолжить работу с остальными
  const errorMessage = $json.errors && $json.errors[0] && $json.errors[0].message
    ? $json.errors[0].message
    : 'неизвестная ошибка генерации';

  return {
    json: {
      ...$('Wait').item.json,
      imageGenerationFailed: true,
      imageErrorText: errorMessage
    }
  };
}

const buffer = Buffer.from(base64Image, 'base64');
const binaryData = await this.helpers.prepareBinaryData(buffer, 'variant.png', 'image/png');

return {
  json: { ...$('Wait').item.json, imageGenerationFailed: false },
  binary: { data: binaryData }
};

const fs = require('fs');
const lockPath = 'D:\\n8n-card-pipeline\\pipeline.lock';
fs.writeFileSync(lockPath, 'locked');

const text = $json.message.text;
const chatId = $json.message.chat.id;

const themeMatch = text.match(/Тема:\s*(.+)/i);
const wishesMatch = text.match(/Пожелания:\s*(.+)/i);

const staticData = $getWorkflowStaticData('global');
const timestamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
const folderPath = `D:\\n8n-card-pipeline\\Card\\${timestamp}`;

const theme = themeMatch ? themeMatch[1].trim() : '';
const wishes = wishesMatch ? wishesMatch[1].trim() : '';

staticData.chatId = chatId;
staticData.folderPath = folderPath;
staticData.previewPaths = [];
staticData.previewPathsByVariant = { 1: [], 2: [], 3: [] };
staticData.startTime = Date.now();
staticData.theme = theme;
staticData.wishes = wishes;
staticData.successCount = 0;
staticData.failureCount = 0;
staticData.consecutiveFailures = 0;

return [{
  json: {
    chatId: chatId,
    theme: theme,
    wishes: wishes,
    folderPath: folderPath
  }
}];

