const rawText = $json.choices[0].message.content;
const cleaned = rawText.replace(/```json|```/g, '').trim();

const staticData = $getWorkflowStaticData('global');

let objects;
try {
  objects = JSON.parse(cleaned);
} catch (e) {
  // Groq не вернул JSON — почти всегда это отказ из-за недопустимого содержания
  // в пожеланиях продюсера (оружие, насилие и т.п.). Не роняем узел ошибкой,
  // а передаём это дальше как обычные данные, чтобы сообщить пользователю.
  return {
    json: {
      chatId: staticData.chatId,
      pipelineError: true,
      errorText:
        '⚠️ Не удалось составить набор по вашим пожеланиям.\n\n' +
        'Вероятная причина: в тексте пожеланий есть что-то недопустимое для ' +
        'детской аудитории (например, оружие, насилие или другой запрещённый ' +
        'элемент).\n\n' +
        'Попробуйте переформулировать пожелания и отправить запрос заново.'
    }
  };
}

return {
  json: {
    chatId: staticData.chatId,
    theme: staticData.theme,
    wishes: staticData.wishes,
    themeObjects: objects,
    pipelineError: false
  }
};

