const sharp = require('sharp');

// Определяем реальное количество пришедших картинок динамически
const binary = $input.first().binary;
const keys = Object.keys(binary)
  .filter(k => k === 'data' || /^data\d+$/.test(k))
  .sort((a, b) => {
    const na = a === 'data' ? 0 : parseInt(a.replace('data', ''));
    const nb = b === 'data' ? 0 : parseInt(b.replace('data', ''));
    return na - nb;
  });

const n = keys.length;

// Подбираем сетку умно: сначала ищем вариант БЕЗ пустых ячеек (или с минимумом
// пустых), среди таких вариантов выбираем тот, чьи пропорции ближе к 2.5:1
// (широкая "лента" карточек, как классические 5x2) — это и даёт для n=10
// правильные 5x2 вместо наивных 4x3 с двумя пустыми клетками
function bestGrid(n) {
  const targetAspect = 2.5;
  const sqrtN = Math.sqrt(n);
  const minCols = Math.max(1, Math.ceil(sqrtN / 1.8));
  const maxCols = Math.max(minCols, Math.ceil(sqrtN * 1.8));

  let best = null;
  for (let cols = minCols; cols <= maxCols; cols++) {
    const rows = Math.ceil(n / cols);
    const waste = cols * rows - n;
    const aspect = cols / rows;
    const aspectDiff = Math.abs(aspect - targetAspect);

    if (
      best === null ||
      waste < best.waste ||
      (waste === best.waste && aspectDiff < best.aspectDiff)
    ) {
      best = { cols, rows, waste, aspectDiff };
    }
  }
  return { cols: best.cols, rows: best.rows };
}

const { cols, rows } = bestGrid(n);
const tileSize = 1024;

const composites = [];
for (let i = 0; i < n; i++) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, keys[i]);
  const resized = await sharp(buffer).resize(tileSize, tileSize, { fit: 'cover' }).toBuffer();
  composites.push({
    input: resized,
    left: (i % cols) * tileSize,
    top: Math.floor(i / cols) * tileSize
  });
}

const canvas = sharp({
  create: {
    width: tileSize * cols,
    height: tileSize * rows,
    channels: 4,
    background: { r: 255, g: 255, b: 255, alpha: 1 }
  }
}).composite(composites).jpeg({ quality: 85 });

