const BASE_HUES = {
  red:           { h: 5,   s: 90, l: 46 },
  blue_sky:      { h: 197, s: 92, l: 47 },
  green:         { h: 140, s: 85, l: 42 },
  yellow_orange: { h: 40,  s: 92, l: 50 },
  violet:        { h: 271, s: 80, l: 50 },
  blue_pale:     { h: 212, s: 88, l: 45 },
  yellow_pale:   { h: 50,  s: 90, l: 52 },
  orange_pale:   { h: 25,  s: 90, l: 48 },
  pink:          { h: 330, s: 85, l: 48 },
};

const CONTRAST_LEVELS = {
  soft:   { dH: 2, dS: 1, dL: 3 },
  medium: { dH: 4, dS: 2, dL: 6 },
  bold:   { dH: 6, dS: 3, dL: 10 },
};

function hslToHex(h, s, l) {
  h = ((h % 360) + 360) % 360;
  s = Math.max(0, Math.min(100, s)) / 100;
  l = Math.max(0, Math.min(100, l)) / 100;
  const c = (1 - Math.abs(2 * l - 1)) * s;
  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
  const m = l - c / 2;
  let r, g, b;
  if (h < 60)       { r = c; g = x; b = 0; }
  else if (h < 120) { r = x; g = c; b = 0; }
  else if (h < 180) { r = 0; g = c; b = x; }
  else if (h < 240) { r = 0; g = x; b = c; }
  else if (h < 300) { r = x; g = 0; b = c; }
  else              { r = c; g = 0; b = x; }
  const toHex = (v) => Math.round((v + m) * 255).toString(16).padStart(2, '0');
  return `#${toHex(r)}${toHex(g)}${toHex(b)}`.toUpperCase();
}

function getColorPair(name, contrast = 'medium') {
  const base = BASE_HUES[name] || BASE_HUES.blue_sky;
  const level = CONTRAST_LEVELS[contrast] || CONTRAST_LEVELS.medium;
  const colorA = hslToHex(base.h, base.s, base.l);
  const colorB = hslToHex(base.h + level.dH, Math.max(base.s - level.dS, 0), Math.min(base.l + level.dL, 95));
  return { a: colorA, b: colorB };
}

// ============================================================
// 2. Точка "происхождения" узора
// ============================================================
function resolveOrigin(layout, width, height) {
  if (layout === 'center') return { x: width / 2, y: height / 2 };
  if (layout === 'bottom') return { x: width / 2, y: height * 0.92 };
  return null;
}

// ============================================================
// 3. Волнистая линия (деформация)
// ============================================================
function wavyLinePath(x, yStart, yEnd, amplitude, wavelength) {
  const len = yEnd - yStart;
  // Плотность точек масштабируется под длину пути и длину волны —
  // не менее ~20 точек на один период синусоиды, иначе волна
  // аппроксимируется прямыми отрезками и превращается в зубчатый зигзаг
  const periods = len / wavelength;
  const steps = Math.max(40, Math.round(periods * 20));

  const points = [];
  for (let i = 0; i <= steps; i++) {
    const y = yStart + (len * i) / steps;
    const offset = amplitude * Math.sin((y / wavelength) * Math.PI * 2);
    points.push({ x: x + offset, y });
  }

  // Соединяем точки квадратичными кривыми Безье через середины отрезков —
  // стандартный приём сглаживания ломаной линии в гладкую кривую,
  // это вторая, независимая подстраховка от острых углов
  let d = `M ${points[0].x} ${points[0].y}`;
  for (let i = 1; i < points.length - 1; i++) {
    const midX = (points[i].x + points[i + 1].x) / 2;
    const midY = (points[i].y + points[i + 1].y) / 2;
    d += ` Q ${points[i].x} ${points[i].y} ${midX} ${midY}`;
  }
  const last = points[points.length - 1];
  d += ` L ${last.x} ${last.y}`;

  return d;
}

// ============================================================
// 4. Генераторы фигур
// ============================================================
function stripesPattern({ width, height, colorA, colorB, orientation = 'vertical', stripeWidth = 110, waviness = 0 }) {
  if (orientation === 'spiral') {
    const cx = width / 2, cy = height / 2;
    const maxR = Math.sqrt(width * width + height * height) / 2;
    const turns = 4;
    let dots = `<rect width="100%" height="100%" fill="${colorB}"/>`;
    for (let i = 0; i < turns * 40; i++) {
      const t = i / (turns * 40);
      const angle = t * turns * 2 * Math.PI;
      const r = t * maxR;
      const x = cx + r * Math.cos(angle);
      const y = cy + r * Math.sin(angle);
      dots += `<circle cx="${x}" cy="${y}" r="${stripeWidth / 2}" fill="${colorA}"/>`;
    }
    return `<svg width="${width}" height="${height}">${dots}</svg>`;
  }
  const angle = orientation === 'horizontal' ? 0 : orientation === 'diagonal' ? 45 : 90;
  const diag = Math.sqrt(width * width + height * height);
  let content = '';
  for (let x = -diag; x < diag; x += stripeWidth * 2) {
    if (waviness > 0) {
      const d = wavyLinePath(x, -diag, diag, stripeWidth * waviness, 220);
      content += `<path d="${d}" stroke="${colorA}" stroke-width="${stripeWidth}" fill="none" stroke-linejoin="round" stroke-linecap="round"/>`;
    } else {
      content += `<rect x="${x}" y="${-diag}" width="${stripeWidth}" height="${diag * 2}" fill="${colorA}"/>`;
    }
  }
  return `<svg width="${width}" height="${height}"><rect width="100%" height="100%" fill="${colorB}"/><g transform="rotate(${angle} ${width / 2} ${height / 2})">${content}</g></svg>`;
}

function diamondsPattern({ width, height, colorA, colorB, layout = 'tiled', baseSize = 95, waviness = 0 }) {
  const origin = resolveOrigin(layout, width, height);
  // Подложка на весь холст — гарантирует отсутствие просветов, даже если
  // где-то на краю фигуры не дотянутся идеально точно до края канваса
  let shapes = `<rect width="100%" height="100%" fill="${colorB}"/>`;
  let idx = 0;
  // Шаг по вертикали — ПОЛОВИНА размера ромба (а не полный размер!):
  // ромб повёрнут на 45°, и соседние ряды должны заходить друг в друга
  // своими верхними/нижними вершинами, чтобы не оставалось зазора
  const rowStep = baseSize / 2;
  for (let row = -1; row * rowStep < height + baseSize; row++) {
    for (let col = -1; col * baseSize < width + baseSize; col++) {
      const offsetX = row % 2 === 0 ? 0 : baseSize / 2;
      const cx = col * baseSize + offsetX, cy = row * rowStep;
      let size = baseSize;
      if (origin) {
        const dist = Math.hypot(cx - origin.x, cy - origin.y);
        size = baseSize * (0.6 + Math.min(dist / 500, 0.8));
      }
      const wobble = waviness > 0 ? Math.sin(cx * 0.05 + cy * 0.05) * waviness * 15 : 0;
      const color = idx % 2 === 0 ? colorA : colorB;
      shapes += `<polygon points="${cx + wobble},${cy - size / 2} ${cx + size / 2},${cy + wobble} ${cx + wobble},${cy + size / 2} ${cx - size / 2},${cy + wobble}" fill="${color}"/>`;
      idx++;
    }
  }
  return `<svg width="${width}" height="${height}">${shapes}</svg>`;
}

function hexagonsPattern({ width, height, colorA, colorB, layout = 'tiled', hexSize = 85 }) {
  const origin = resolveOrigin(layout, width, height);
  const w = hexSize * 2, h = hexSize * Math.sqrt(3);
  let shapes = '';
  for (let row = -1; row * h * 0.75 < height + h; row++) {
    for (let col = -1; col * w < width + w; col++) {
      const offsetX = row % 2 === 0 ? 0 : w / 2;
      const cx = col * w + offsetX, cy = row * h * 0.75;
      let size = hexSize;
      if (origin) {
        const dist = Math.hypot(cx - origin.x, cy - origin.y);
        size = hexSize * (0.6 + Math.min(dist / 500, 0.8));
      }
      const color = (row + col) % 2 === 0 ? colorA : colorB;
      const points = [...Array(6)].map((_, i) => {
        const a = (Math.PI / 3) * i;
        return `${cx + size * Math.cos(a)},${cy + size * Math.sin(a)}`;
      }).join(' ');
      shapes += `<polygon points="${points}" fill="${color}"/>`;
    }
  }
  return `<svg width="${width}" height="${height}">${shapes}</svg>`;
}

function circlesPattern({ width, height, colorA, colorB, layout = 'tiled', baseSize = 70 }) {
  if (layout === 'tiled') {
    let shapes = `<rect width="100%" height="100%" fill="${colorB}"/>`;
    for (let row = -1; row * baseSize * 1.4 < height + baseSize; row++) {
      for (let col = -1; col * baseSize * 1.4 < width + baseSize; col++) {
        const offsetX = row % 2 === 0 ? 0 : baseSize * 0.7;
        const cx = col * baseSize * 1.4 + offsetX, cy = row * baseSize * 1.4;
        shapes += `<circle cx="${cx}" cy="${cy}" r="${baseSize / 2}" fill="${colorA}"/>`;
      }
    }
    return `<svg width="${width}" height="${height}">${shapes}</svg>`;
  }
  const origin = resolveOrigin(layout, width, height);
  const maxR = Math.hypot(width, height);
  let rings = '';
  let i = 0;
  for (let r = maxR; r > 0; r -= baseSize) {
    rings += `<circle cx="${origin.x}" cy="${origin.y}" r="${r}" fill="${i % 2 === 0 ? colorA : colorB}"/>`;
    i++;
  }
  return `<svg width="${width}" height="${height}">${rings}</svg>`;
}

function trianglesPattern({ width, height, colorA, colorB, layout = 'tiled', rayCount = 28, size = 100 }) {
  if (layout === 'tiled') {
    let shapes = '';
    let idx = 0;
    for (let row = -1; row * size * 0.87 < height + size; row++) {
      for (let col = -1; col * size < width + size; col++) {
        const offsetX = row % 2 === 0 ? 0 : size / 2;
        const x = col * size + offsetX, y = row * size * 0.87;
        const flip = (row + col) % 2 === 0 ? 1 : -1;
        const color = idx % 2 === 0 ? colorA : colorB;
        shapes += `<polygon points="${x},${y} ${x + size},${y} ${x + size / 2},${y + flip * size * 0.87}" fill="${color}"/>`;
        idx++;
      }
    }
    return `<svg width="${width}" height="${height}">${shapes}</svg>`;
  }
  const origin = resolveOrigin(layout, width, height);
  const maxR = Math.hypot(width, height);
  let rays = '';
  for (let i = 0; i < rayCount; i++) {
    const a1 = (i / rayCount) * 2 * Math.PI;
    const a2 = ((i + 1) / rayCount) * 2 * Math.PI;
    const color = i % 2 === 0 ? colorA : colorB;
    rays += `<path d="M${origin.x},${origin.y} L${origin.x + maxR * Math.cos(a1)},${origin.y + maxR * Math.sin(a1)} L${origin.x + maxR * Math.cos(a2)},${origin.y + maxR * Math.sin(a2)} Z" fill="${color}"/>`;
  }
  return `<svg width="${width}" height="${height}">${rays}</svg>`;
}

function squaresPattern({ width, height, colorA, colorB, layout = 'tiled', baseSize = 100 }) {
  if (layout === 'tiled') {
    let shapes = '';
    for (let row = -1; row * baseSize < height + baseSize; row++) {
      for (let col = -1; col * baseSize < width + baseSize; col++) {
        const color = (row + col) % 2 === 0 ? colorA : colorB;
        shapes += `<rect x="${col * baseSize}" y="${row * baseSize}" width="${baseSize}" height="${baseSize}" fill="${color}"/>`;
      }
    }
    return `<svg width="${width}" height="${height}">${shapes}</svg>`;
  }
  const origin = resolveOrigin(layout, width, height);
  const maxSize = Math.max(width, height) * 1.5;
  let frames = '';
  let i = 0;
  for (let s = maxSize; s > 0; s -= baseSize) {
    const color = i % 2 === 0 ? colorA : colorB;
    frames += `<rect x="${origin.x - s / 2}" y="${origin.y - s / 2}" width="${s}" height="${s}" fill="${color}"/>`;
    i++;
  }
  return `<svg width="${width}" height="${height}">${frames}</svg>`;
}

function generateBackgroundSVG({ shape, layout, orientation, waviness, colorPairName, contrast, width, height }) {
  const pair = getColorPair(colorPairName, contrast);
  const params = { width, height, colorA: pair.a, colorB: pair.b, layout, orientation, waviness };
  switch (shape) {
    case 'stripes':   return stripesPattern(params);
    case 'diamonds':  return diamondsPattern(params);
    case 'circles':   return circlesPattern(params);
    case 'squares':   return squaresPattern(params);
    default:          return stripesPattern(params);
  }
}

// ============================================================
// 5. Забираем уже готовый чистый вырез (сделан нейросетью в предыдущем узле)
// ============================================================
const cutoutBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');

// ============================================================
// 6. Генерируем фон по параметрам от Groq
// ============================================================
const bgSVG = generateBackgroundSVG({
  shape: $json.patternShape,
  layout: $json.patternLayout || 'tiled',
  orientation: $json.patternOrientation || 'vertical',
  waviness: Number($json.patternWaviness) || 0,
  colorPairName: $json.colorPair,
  contrast: $json.patternContrast || 'medium',
  width: 1024,
  height: 1024
});
let bgBuffer = await sharp(Buffer.from(bgSVG)).png().toBuffer();

// ============================================================
// 5.2 Для категории 2 — рисуем полноразмерную однотонную поверхность
// программно (сама поверхность больше не рисуется нейросетью, чтобы
// избежать круглых "подставок" вместо полноразмерной плоскости —
// нейросеть-сегментатор не умеет отличать "поверхность, которую надо
// оставить" от "фон, который надо вырезать", поэтому эта задача
// полностью передана коду)
// ============================================================
if ($json.category === 2) {
  const surfaceInfo = await sharp(cutoutBuffer).ensureAlpha().raw().toBuffer({ resolveWithObject: true });
  const { data: surfData, info: surfInfo } = surfaceInfo;

  let maxYSurface = 0;
  for (let y = 0; y < surfInfo.height; y++) {
    for (let x = 0; x < surfInfo.width; x++) {
      const alpha = surfData[(y * surfInfo.width + x) * 4 + 3];
      if (alpha > 100 && y > maxYSurface) maxYSurface = y;
    }
  }

  // Граница поверхности поднята заметно выше нижней точки предмета (180px
  // вместо прежних 20) — раньше предмет казался стоящим на самом краю узкой
  // полоски, теперь у него достаточно пространства на поверхности
  const SURFACE_RISE = 180;
  const surfaceTopY = Math.max(0, maxYSurface - SURFACE_RISE);

  // Отдельный оттенок той же цветовой семьи, что и узор, но заметно темнее —
  // чтобы поверхность отличалась от фона, а не сливалась с одним из его цветов
  const basePair = BASE_HUES[$json.colorPair] || BASE_HUES.blue_sky;
  const surfaceColor = hslToHex(basePair.h, Math.min(basePair.s + 5, 100), Math.max(basePair.l - 14, 5));

  const surfaceHeight = 1024 - surfaceTopY;
  const surfaceSVG = `
    <svg width="1024" height="1024">
      <defs>
        <linearGradient id="sheen" x1="0%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%" stop-color="white" stop-opacity="0.22"/>
          <stop offset="18%" stop-color="white" stop-opacity="0.06"/>
          <stop offset="40%" stop-color="white" stop-opacity="0"/>
        </linearGradient>
      </defs>
      <rect x="0" y="${surfaceTopY}" width="1024" height="${surfaceHeight}" fill="${surfaceColor}"/>
      <rect x="0" y="${surfaceTopY}" width="1024" height="${surfaceHeight}" fill="url(#sheen)"/>
    </svg>
  `;
  const surfaceBuffer = await sharp(Buffer.from(surfaceSVG)).png().toBuffer();
  bgBuffer = await sharp(bgBuffer)
    .composite([{ input: surfaceBuffer }])
    .png()
    .toBuffer();
}

// ============================================================
// 5.1 Для категорий 1 и 2 — мягкое свечение в центре фона позади предмета,
// чтобы предмет визуально не сливался с узором (как на референсах)
// ============================================================
if ($json.category === 1 || $json.category === 2) {
  const glowSVG = `
    <svg width="1024" height="1024">
      <defs>
        <radialGradient id="glow" cx="50%" cy="50%" r="50%">
          <stop offset="0%" stop-color="white" stop-opacity="0.32"/>
          <stop offset="45%" stop-color="white" stop-opacity="0.12"/>
          <stop offset="100%" stop-color="white" stop-opacity="0"/>
        </radialGradient>
      </defs>
      <rect width="100%" height="100%" fill="url(#glow)"/>
    </svg>
  `;
  const glowBuffer = await sharp(Buffer.from(glowSVG)).png().toBuffer();
  bgBuffer = await sharp(bgBuffer)
    .composite([{ input: glowBuffer, blend: 'screen' }])
    .png()
    .toBuffer();
}

// ============================================================
// 6.1 Для категорий 2 и 3 — рисуем контролируемую тень предмета
// на поверхность (программно, а не полагаясь на нейросеть)
// ============================================================
if ($json.category === 2 || $json.category === 3) {
  const cutoutInfo = await sharp(cutoutBuffer).ensureAlpha().raw().toBuffer({ resolveWithObject: true });
  const { data: cData, info: cInfo } = cutoutInfo;

  // Находим нижнюю границу непрозрачной области предмета (по X) —
  // именно там должна лежать тень
  let minX = cInfo.width, maxX = 0, maxY = 0;
  for (let y = 0; y < cInfo.height; y++) {
    for (let x = 0; x < cInfo.width; x++) {
      const alpha = cData[(y * cInfo.width + x) * 4 + 3];
      if (alpha > 100) {
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y > maxY) maxY = y;
      }
    }
  }

  if (maxX > minX) {
    const shadowCx = (minX + maxX) / 2;
    const shadowCy = maxY - 8; // чуть выше самого нижнего края предмета
    const shadowRx = (maxX - minX) * 0.38;
    const shadowRy = shadowRx * 0.22;

    const shadowSVG = `
      <svg width="${cInfo.width}" height="${cInfo.height}">
        <defs>
          <filter id="blur"><feGaussianBlur stdDeviation="14"/></filter>
        </defs>
        <ellipse cx="${shadowCx}" cy="${shadowCy}" rx="${shadowRx}" ry="${shadowRy}"
                 fill="black" opacity="0.28" filter="url(#blur)"/>
      </svg>
    `;
    const shadowBuffer = await sharp(Buffer.from(shadowSVG)).png().toBuffer();
    bgBuffer = await sharp(bgBuffer)
      .composite([{ input: shadowBuffer, blend: 'multiply' }])
      .png()
      .toBuffer();
  }
}

// ============================================================
// 7. Совмещаем: фон снизу, готовый вырез сверху
// ============================================================
const finalBuffer = await sharp(bgBuffer)
  .composite([{ input: cutoutBuffer, gravity: 'center' }])
  .png()
  .toBuffer();

const finalBinary = await this.helpers.prepareBinaryData(finalBuffer, 'variant.png', 'image/png');

return { json: $json, binary: { data: finalBinary } };

const sharp = require('sharp');

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const metadata = await sharp(buffer).metadata();
const width = metadata.width;
const height = metadata.height;

// Диагональный градиент — имитация направленного ключевого света:
// светлее в одном углу, темнее в противоположном
const gradientSVG = `
  <svg width="${width}" height="${height}">
    <defs>
      <linearGradient id="light" x1="15%" y1="10%" x2="85%" y2="90%">
        <stop offset="0%" stop-color="white" stop-opacity="0.38"/>
        <stop offset="50%" stop-color="white" stop-opacity="0"/>
        <stop offset="100%" stop-color="black" stop-opacity="0.28"/>
      </linearGradient>
    </defs>
    <rect width="100%" height="100%" fill="url(#light)"/>
  </svg>
`;
const gradientBuffer = await sharp(Buffer.from(gradientSVG)).png().toBuffer();

const finalBuffer = await sharp(buffer)
  .composite([{ input: gradientBuffer, blend: 'soft-light' }])
  .png()
  .toBuffer();

const finalBinary = await this.helpers.prepareBinaryData(finalBuffer, 'variant.png', 'image/png');

return { json: $json, binary: { data: finalBinary } };

// Восстанавливаем поля карточки (theme, category, patternShape и т.д.),
// которые были стёрты двумя HTTP Request узлами подряд (удаление фона + скачивание)
return {
  json: $('Декодирование base').item.json,
  binary: $binary
};

const fs = require('fs');
const lockPath = 'D:\\n8n-card-pipeline\\pipeline.lock';

if (fs.existsSync(lockPath)) {
  fs.unlinkSync(lockPath);
}

return { json: $json };

// Разворачиваем список из 10 карточек в список из 30 "рабочих элементов" —
// каждая карточка трижды, с явным номером варианта. Вся дальнейшая цепочка
// (генерация, удаление фона, замена фона, сохранение) отработает для каждой
// записи одинаково, без изменений в своей логике.
const items = $input.all();
const expanded = [];

for (const item of items) {
  for (let variantIndex = 1; variantIndex <= 3; variantIndex++) {
    expanded.push({
      json: { ...item.json, variantIndex }
    });
  }
}

return expanded;

const staticData = $getWorkflowStaticData('global');
if (!staticData.previewPathsByVariant) {
  staticData.previewPathsByVariant = { 1: [], 2: [], 3: [] };
}

const originalData = $('Создание папки через fs-модуль').item.json;
const v = originalData.variantIndex;

staticData.previewPathsByVariant[v].push($json.filePath || $json.fileName);
staticData.successCount = (staticData.successCount || 0) + 1;
staticData.consecutiveFailures = 0;

return $input.all();

const staticData = $getWorkflowStaticData('global');
if (!staticData.previewPathsByVariant) {
  staticData.previewPathsByVariant = { 1: [], 2: [], 3: [] };
}

// Пропускаем группы, где вообще нет ни одной успешной картинки —
// иначе цикл "Loop по вариантам превью" может зависнуть, пытаясь
// обработать пустую группу и не имея данных, чтобы замкнуться обратно
const groups = [1, 2, 3]
  .map(v => ({
    variantIndex: v,
    paths: staticData.previewPathsByVariant[v] || [],
    chatId: staticData.chatId
  }))
  .filter(g => g.paths.length > 0)
  .map(g => ({ json: g }));

return groups;

const group = $input.first().json;

return group.paths.map(p => ({
  json: {
    path: p,
    chatId: group.chatId,
    variantIndex: group.variantIndex
  }
}));

const staticData = $getWorkflowStaticData('global');
staticData.failureCount = (staticData.failureCount || 0) + 1;
staticData.consecutiveFailures = (staticData.consecutiveFailures || 0) + 1;

const FAILURE_NOTIFY_THRESHOLD = 3;
const shouldNotify = staticData.consecutiveFailures <= FAILURE_NOTIFY_THRESHOLD;

let text = '';
if (shouldNotify) {
  text =
    '⚠️ Не удалось сгенерировать один из вариантов карточки "' + $json.name +
    '" (категория ' + $json.category + ', вариант ' + $json.variantIndex + ').\n' +
    'Причина: ' + ($json.imageErrorText || 'неизвестная ошибка') + '\n\n' +
    'Остальные карточки продолжают генерироваться.';

  if (staticData.consecutiveFailures === FAILURE_NOTIFY_THRESHOLD) {
    text += '\n\n(Похоже на системную проблему — дальнейшие такие уведомления временно ' +
      'скрою, чтобы не засорять чат, итог будет в финальном отчёте.)';
  }
}

return {
  json: {
    chatId: staticData.chatId,
    shouldNotify: shouldNotify,
    text: text
  }
};
